  7→const MAX_RETRIES = 3;
  8→const RETRY_BASE_DELAY = 1000; // 1 second
  9→
 10→export type UploadedFile = {
 11→  cid: string;
 12→  size: number;
 13→  iv: string;
 14→  wrappedKey: string;
 15→  originalName: string;
 16→  originalSize: number;
 17→  encryptionMode: 'GCM' | 'CTR';
 18→};
 19→
 20→/**
 21→ * Retry wrapper with exponential backoff.
 22→ * Does not retry cancelled operations.
 23→ */
 24→async function withRetry<T>(
 25→  fn: () => Promise<T>,
 26→  maxRetries: number = MAX_RETRIES,
 27→  baseDelay: number = RETRY_BASE_DELAY
 28→): Promise<T> {
 29→  let lastError: Error = new Error('Retry failed');
 30→
 31→  for (let attempt = 0; attempt < maxRetries; attempt++) {
 32→    try {
 33→      return await fn();
 34→    } catch (error) {
 35→      lastError = error as Error;
 36→      // Don't retry if cancelled
 37→      if ((error as Error).message === 'Upload cancelled by user') {
 38→        throw error;
 39→      }
 40→      if (attempt < maxRetries - 1) {
 41→        const delay = baseDelay * Math.pow(2, attempt);
 42→        await new Promise((resolve) => setTimeout(resolve, delay));
 43→      }
 44→    }
 45→  }
 46→
 47→  throw lastError;
 48→}
