 50→/**
 51→ * Upload a single file: encrypt then upload to IPFS.
 52→ */
 53→export async function uploadFile(
 54→  file: File,
 55→  userPublicKey: Uint8Array,
 56→  onProgress?: (percent: number) => void,
 57→  cancelToken?: CancelToken
 58→): Promise<UploadedFile> {
 59→  // 1. Encrypt the file
 60→  const encrypted: EncryptedFileResult = await encryptFile(file, userPublicKey);
 61→
 62→  // 2. Upload to IPFS with retry
 63→  // Cast to ArrayBuffer for TypeScript 5.9 compatibility (Uint8Array.buffer is ArrayBufferLike)
 64→  const blob = new Blob([encrypted.ciphertext.buffer as ArrayBuffer], {
 65→    type: 'application/octet-stream',
 66→  });
 67→  const result: AddResponse = await withRetry(() => addToIpfs(blob, onProgress, cancelToken));
 68→
 69→  return {
 70→    cid: result.cid,
 71→    size: result.size,
 72→    iv: encrypted.iv,
 73→    wrappedKey: encrypted.wrappedKey,
 74→    originalName: file.name,
 75→    originalSize: encrypted.originalSize,
 76→    encryptionMode: encrypted.encryptionMode,
 77→  };
 78→}
