 80→/**
 81→ * Upload multiple files sequentially.
 82→ * Pre-checks quota and tracks progress via upload store.
 83→ */
 84→export async function uploadFiles(
 85→  files: File[],
 86→  userPublicKey: Uint8Array
 87→): Promise<UploadedFile[]> {
 88→  const uploadStore = useUploadStore.getState();
 89→  const quotaStore = useQuotaStore.getState();
 90→
 91→  // Calculate total size
 92→  const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 93→
 94→  // Pre-check quota
 95→  if (!quotaStore.canUpload(totalSize)) {
 96→    throw new Error(
 97→      `Not enough space (${Math.round(quotaStore.usedBytes / 1024 / 1024)} of ${Math.round(quotaStore.limitBytes / 1024 / 1024)}MB used)`
 98→    );
 99→  }
100→
101→  uploadStore.startUpload(files.length);
102→  const results: UploadedFile[] = [];
103→
104→  try {
105→    // Sequential uploads per CONTEXT.md decision
106→    for (const file of files) {
107→      const cancelSource = useUploadStore.getState().cancelSource;
108→      if (useUploadStore.getState().status === 'cancelled') {
109→        throw new Error('Upload cancelled by user');
110→      }
111→
112→      uploadStore.setEncrypting(file.name);
113→
114→      const result = await uploadFile(
115→        file,
116→        userPublicKey,
117→        (percent) => uploadStore.setUploading(file.name, percent),
118→        cancelSource?.token
119→      );
120→
121→      results.push(result);
122→      uploadStore.fileComplete();
123→    }
124→
125→    uploadStore.setSuccess();
126→    return results;
127→  } catch (error) {
128→    const message = (error as Error).message;
129→    if (message !== 'Upload cancelled by user') {
130→      uploadStore.setError(message);
131→      console.error('Upload failed:', error);
132→    }
133→    throw error;
134→  } finally {
135→    // Refresh quota from server (authoritative source after atomic upload)
136→    await useQuotaStore.getState().fetchQuota();
137→  }
138→}
