 1→import axios from 'axios';
 2→import { useAuthStore } from '../../stores/auth.store';
 3→import { clearAllUserStores } from '../clear-user-stores';
 4→
 5→// Shared refresh promise eliminates race condition where multiple concurrent
 6→// 401 responses each trigger their own POST /auth/refresh before the boolean
 7→// flag could be set. The promise is assigned synchronously before any await,
 8→// so all concurrent 401 handlers see it immediately and share the same refresh.
 9→let refreshPromise: Promise<string> | null = null;
10→
11→export const apiClient = axios.create({
12→  baseURL: import.meta.env.VITE_API_URL || 'http://localhost:3000',
13→  withCredentials: true, // For HTTP-only refresh token cookie
14→});
15→
16→// Request interceptor: Add access token to headers
17→apiClient.interceptors.request.use((config) => {
18→  const accessToken = useAuthStore.getState().accessToken;
19→  if (accessToken) {
20→    config.headers.Authorization = `Bearer ${accessToken}`;
21→  }
22→  return config;
23→});
24→
25→// Response interceptor: Handle 401 and token refresh
26→apiClient.interceptors.response.use(
27→  (response) => response,
28→  async (error) => {
29→    const originalRequest = error.config;
30→
31→    // Don't retry refresh endpoint to avoid infinite loop
32→    const isRefreshRequest = originalRequest?.url?.includes('/auth/refresh');
33→
34→    // Only handle 401 errors, and only retry once (but never retry refresh endpoint)
35→    if (error.response?.status === 401 && !originalRequest._retry && !isRefreshRequest) {
36→      originalRequest._retry = true;
37→
38→      // If a refresh is already in flight, all concurrent 401 handlers
39→      // await the same promise instead of firing duplicate refresh requests.
40→      if (refreshPromise) {
41→        const token = await refreshPromise;
42→        originalRequest.headers.Authorization = `Bearer ${token}`;
43→        return apiClient(originalRequest);
44→      }
45→
46→      // First 401 handler: create the refresh promise synchronously (before any await)
47→      // so subsequent 401 handlers in the same microtask see it immediately.
48→      refreshPromise = apiClient
49→        .post<{ accessToken: string }>('/auth/refresh')
50→        .then((response) => {
51→          const { accessToken } = response.data;
52→          useAuthStore.getState().setAccessToken(accessToken);
53→          return accessToken;
54→        })
55→        .catch((refreshError) => {
56→          // [SECURITY: HIGH-03] Clear all stores including crypto keys on token refresh failure
57→          clearAllUserStores();
58→          // Redirect to login will be handled by route guard
59→          throw refreshError;
60→        })
61→        .finally(() => {
62→          refreshPromise = null;
63→        });
64→
65→      const token = await refreshPromise;
66→      originalRequest.headers.Authorization = `Bearer ${token}`;
67→      return apiClient(originalRequest);
68→    }
69→
70→    throw error;
71→  }
72→);
