10→import { selectEncryptionMode, encryptFileCtr } from './streaming-crypto.service';
11→
12→export type EncryptedFileResult = {
13→  ciphertext: Uint8Array;
14→  iv: string; // hex-encoded for API
15→  wrappedKey: string; // hex-encoded for storage
16→  originalSize: number;
17→  encryptedSize: number;
18→  encryptionMode: 'GCM' | 'CTR';
19→};
20→
21→/**
22→ * Encrypt a file using the appropriate encryption mode.
23→ *
24→ * Media files above 256KB use AES-256-CTR (streaming, random-access decryption).
25→ * All other files use AES-256-GCM (authenticated encryption).
26→ *
27→ * Mode selection is transparent to the caller -- both paths return the same
28→ * EncryptedFileResult type with the encryptionMode field set accordingly.
29→ *
30→ * @param file - The file to encrypt
31→ * @param userPublicKey - User's secp256k1 public key (65 bytes, uncompressed)
32→ * @returns Encrypted file data with wrapped key and IV
33→ */
34→export async function encryptFile(
35→  file: File,
36→  userPublicKey: Uint8Array
37→): Promise<EncryptedFileResult> {
38→  const mode = selectEncryptionMode(file);
39→
40→  // CTR path: streaming 1MB chunks for media files
41→  if (mode === 'CTR') {
42→    return encryptFileCtr(file, userPublicKey);
43→  }
44→
45→  // GCM path: full-buffer authenticated encryption
46→  // 1. Generate unique file key and IV
47→  const fileKey = generateFileKey();
48→  const iv = generateIv();
49→
50→  // 2. Read file as ArrayBuffer
51→  const plaintext = new Uint8Array(await file.arrayBuffer());
52→  const originalSize = plaintext.length;
53→
54→  // 3. Encrypt with AES-256-GCM
55→  const ciphertext = await encryptAesGcm(plaintext, fileKey, iv);
56→
57→  // 4. Wrap file key with user's public key (ECIES)
58→  const wrappedKey = await wrapKey(fileKey, userPublicKey);
59→
60→  // 5. Clear sensitive key from memory
61→  clearBytes(fileKey);
62→
63→  return {
64→    ciphertext,
65→    iv: bytesToHex(iv),
66→    wrappedKey: bytesToHex(wrappedKey),
67→    originalSize,
68→    encryptedSize: ciphertext.length,
69→    encryptionMode: 'GCM' as const,
70→  };
71→}
